import asyncio


async def slow(ms):
    await asyncio.sleep(ms / 1000)
    return "ok"


async def main(ms, limit):
    try:
        return await asyncio.wait_for(slow(ms), limit / 1000)
    except asyncio.TimeoutError:
        return "timeout"


def try_wait(ms, limit):
    return asyncio.run(main(ms, limit))

